import { useMemo } from 'react';

import { useSubFilters } from 'hooks';

import { resolveDeepDiveMock } from '../__mocks__/Waterfall/resolveDeepDiveMock';
import { getPerformanceAndBreakdownActiveViewBy } from '../config/performanceAndBreakdownDeepDive';
import {
  PERFORMANCE_AND_BREAKDOWN_MOCK_FORCE_BY_SECTION,
  PERFORMANCE_AND_BREAKDOWN_MOCK_ONLY,
  PERFORMANCE_AND_BREAKDOWN_WATERFALL_OPTIONS_STATE_KEY,
} from '../constants';
import type {
  PerformanceAndBreakdownDeepDiveDataResult,
  PerformanceAndBreakdownInnovationStageFilter,
  PerformanceAndBreakdownMockForceFlags,
  PerformanceAndBreakdownSectionDataResult,
  PerformanceAndBreakdownWaterfallContextKey,
} from '../types';
import { usePerformanceAndBreakdownFilters } from './usePerformanceAndBreakdownFilters';

const noopRefetch = () => Promise.resolve();

function resolveMockView<T>(
  mockOnly: boolean,
  flags: PerformanceAndBreakdownMockForceFlags,
  getReadyData: () => T,
): PerformanceAndBreakdownSectionDataResult<T> {
  if (!mockOnly || flags.skeleton) {
    return { view: 'loading', data: null, refetch: noopRefetch };
  }

  if (flags.error) {
    return { view: 'error', data: null, refetch: noopRefetch };
  }

  if (flags.empty) {
    return { view: 'empty', data: null, refetch: noopRefetch };
  }

  return {
    view: 'ready',
    data: getReadyData(),
    refetch: noopRefetch,
  };
}

export function usePerformanceAndBreakdownDeepDiveData(
  contextKey: PerformanceAndBreakdownWaterfallContextKey,
  innovationStageFilter: PerformanceAndBreakdownInnovationStageFilter | null = null,
): PerformanceAndBreakdownDeepDiveDataResult {
  const { applied } = usePerformanceAndBreakdownFilters();
  const { activeSubFilters } = useSubFilters();

  return useMemo((): PerformanceAndBreakdownDeepDiveDataResult => {
    return resolveMockView(
      PERFORMANCE_AND_BREAKDOWN_MOCK_ONLY,
      PERFORMANCE_AND_BREAKDOWN_MOCK_FORCE_BY_SECTION.deepDive,
      () => {
        const activeViewBy = getPerformanceAndBreakdownActiveViewBy(
          contextKey,
          activeSubFilters?.[
            PERFORMANCE_AND_BREAKDOWN_WATERFALL_OPTIONS_STATE_KEY
          ],
        );

        return resolveDeepDiveMock({
          activeViewBy,
          contextKey,
          applied,
          innovationStage: innovationStageFilter?.value,
        });
      },
    );
  }, [activeSubFilters, applied, contextKey, innovationStageFilter?.value]);
}
